def risk_link(code):
    return f"[[{RISKS[code]}#Пример атаки\\|{code}]]"


def codes_cell(val):
    if val == "\u2014":
        return "\u2014"
    parts = [p.strip() for p in val.split(",")]
    return ", ".join(risk_link(p) for p in parts)


def scenario_link(primary, text):
    note = RISKS[primary]
    return f"[[{note}#Пример атаки\\|{text}]]"


def rating_cell(mid, val):
    val = val.strip()
    if val == "\u2014":
        return "\u2014"
    if val == "\u043c\u0435\u0442\u0430":
        return "[[45-agentdojo-benchmark#\u041e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435\\|\u043c\u0435\u0442\u0430]]"
    file, anchor = METHODS[mid]
    return f"[[{file}#{anchor}\\|{val}]]"


def header_method(mid):
    file, _anchor = METHODS[mid]
    return f"[[{file}#Определение\\|{mid}]]"


